"use client"

import { useState } from "react"
import { useWorldStore } from "@/store/worldStore"
import { useUiStore } from "@/store/uiStore"
import { CIV_COLORS, CIV_ICONS, CIV_NAMES } from "@/lib/civColors"
import type { CivState } from "@/types"

const CIV_ORDER = ["ironhold", "verdant", "merchants", "conclave"]

function moodLabel(score: number): string {
  if (score >= 60) return "ALLIED"
  if (score >= 20) return "FRIENDLY"
  if (score >= -20) return "NEUTRAL"
  if (score >= -60) return "HOSTILE"
  return "AT WAR"
}

export default function CivPanel() {
  const civStates = useWorldStore((s) => s.civStates)
  const prevCivStates = useWorldStore((s) => s.prevCivStates)
  const tileHistory = useWorldStore((s) => s.tileHistory)
  const focusedCiv = useUiStore((s) => s.focusedCiv)
  const toggleFocusedCiv = useUiStore((s) => s.toggleFocusedCiv)

  if (!civStates || Object.keys(civStates).length === 0) {
    return (
      <div className="flex items-center justify-center h-full gap-4">
        {CIV_ORDER.map((id) => (
          <div key={id} className="flex-1 h-20 rounded-xl bg-zinc-900/50 border border-zinc-800 animate-pulse" />
        ))}
      </div>
    )
  }

  // Find max values for relative bar scaling
  const allStates = Object.values(civStates)
  const maxGold = Math.max(...allStates.map((s) => s.resources.gold), 1)
  const maxFood = Math.max(...allStates.map((s) => s.resources.food), 1)
  const maxMilitary = Math.max(...allStates.map((s) => s.resources.military), 1)

  return (
    <div className="flex gap-3 h-full">
      {CIV_ORDER.map((civId) => {
        const state = civStates[civId]
        if (!state) return null
        return (
          <CivCard
            key={civId}
            civId={civId}
            state={state}
            prev={prevCivStates[civId]}
            history={tileHistory[civId] ?? []}
            maxGold={maxGold}
            maxFood={maxFood}
            maxMilitary={maxMilitary}
            isFocused={focusedCiv === civId}
            anyFocused={focusedCiv !== null}
            onFocus={() => toggleFocusedCiv(civId)}
          />
        )
      })}
    </div>
  )
}

function CivCard({
  civId, state, prev, history, maxGold, maxFood, maxMilitary, isFocused, anyFocused, onFocus,
}: {
  civId: string
  state: CivState
  prev: CivState | undefined
  history: number[]
  maxGold: number
  maxFood: number
  maxMilitary: number
  isFocused: boolean
  anyFocused: boolean
  onFocus: () => void
}) {
  const color = CIV_COLORS[civId] ?? "#6b7280"
  const icon = CIV_ICONS[civId] ?? "🏛️"
  const name = CIV_NAMES[civId] ?? civId
  const alive = state.is_alive
  const justEliminated = !alive && prev?.is_alive === true

  return (
    <button
      type="button"
      onClick={onFocus}
      aria-label={`Focus ${name} on the map`}
      aria-pressed={isFocused}
      className={`flex-1 text-left rounded-xl border px-3 py-2.5 transition-all cursor-pointer ${
        alive
          ? "bg-zinc-900/80 border-zinc-800"
          : "bg-zinc-950 border-zinc-900 opacity-40 grayscale"
      } ${justEliminated ? "civ-eliminate" : ""} ${
        anyFocused && !isFocused ? "opacity-50" : ""
      }`}
      style={
        alive
          ? { borderColor: isFocused ? color : `${color}33`, boxShadow: isFocused ? `0 0 12px ${color}44` : undefined }
          : {}
      }
    >
      {/* Header */}
      <div className="flex items-center gap-2 mb-2">
        <span className="text-sm">{icon}</span>
        <div className="min-w-0 flex-1">
          <div className="text-xs font-semibold text-zinc-100 truncate">{name}</div>
          <div className="flex items-center gap-1.5 mt-0.5">
            <span
              className="text-[10px] font-medium px-1.5 py-0.5 rounded"
              style={{ background: `${color}20`, color }}
            >
              {state.tile_count} tiles
              <Trend now={state.tile_count} before={prev?.tile_count} />
            </span>
            {!alive && (
              <span className="text-[10px] text-zinc-600 font-medium">
                ELIMINATED
              </span>
            )}
          </div>
        </div>
        {history.length >= 2 && <Sparkline points={history} color={color} />}
      </div>

      {/* Resource bars */}
      <div className="space-y-1.5">
        <ResourceBar
          label="💰" value={state.resources.gold} before={prev?.resources.gold}
          max={maxGold} color="#f59e0b"
        />
        <ResourceBar
          label="🌾" value={state.resources.food} before={prev?.resources.food}
          max={maxFood} color="#22c55e"
        />
        <ResourceBar
          label="⚔️" value={state.resources.military} before={prev?.resources.military}
          max={maxMilitary} color="#ef4444"
        />
      </div>

      {/* Last action */}
      {state.last_action && alive && (
        <div className="mt-2 text-[10px] text-zinc-500 truncate">
          → {state.last_action.replace(/_/g, " ")}
        </div>
      )}

      {/* Relationships */}
      <div className="flex gap-1 mt-2">
        {Object.entries(state.relationships ?? {}).map(([otherId, score]) => (
          <RelDot key={otherId} civId={otherId} score={score as number} />
        ))}
      </div>
    </button>
  )
}

function Trend({ now, before }: { now: number; before: number | undefined }) {
  if (before === undefined || now === before) return null
  return now > before
    ? <span className="ml-1 text-green-400">↑</span>
    : <span className="ml-1 text-red-400">↓</span>
}

function Sparkline({ points, color }: { points: number[]; color: string }) {
  const w = 44
  const h = 16
  const max = Math.max(...points, 1)
  const min = Math.min(...points)
  const range = Math.max(max - min, 1)
  const coords = points
    .map((v, i) => {
      const x = (i / (points.length - 1)) * (w - 2) + 1
      const y = h - 2 - ((v - min) / range) * (h - 4)
      return `${x.toFixed(1)},${y.toFixed(1)}`
    })
    .join(" ")

  return (
    <svg width={w} height={h} className="flex-shrink-0 opacity-80" aria-hidden="true">
      <polyline points={coords} fill="none" stroke={color} strokeWidth="1.25" />
    </svg>
  )
}

function ResourceBar({
  label, value, before, max, color,
}: {
  label: string; value: number; before: number | undefined; max: number; color: string
}) {
  const pct = Math.min(100, (value / max) * 100)
  const delta =
    before === undefined || Math.round(value) === Math.round(before)
      ? null
      : value > before
  return (
    <div className="flex items-center gap-1.5">
      <span className="text-[10px] w-4 flex-shrink-0">{label}</span>
      <div className="flex-1 h-1.5 bg-zinc-800 rounded-full overflow-hidden">
        <div
          className="h-full rounded-full transition-all duration-700"
          style={{ width: `${pct}%`, background: color }}
        />
      </div>
      <span className="text-[10px] text-zinc-500 w-8 text-right tabular-nums">
        {Math.round(value)}
      </span>
      <span className="w-2 text-[10px]" aria-hidden="true">
        {delta === true && <span className="text-green-400">↑</span>}
        {delta === false && <span className="text-red-400">↓</span>}
      </span>
    </div>
  )
}

function RelDot({ civId, score }: { civId: string; score: number }) {
  const [hover, setHover] = useState(false)
  const color = CIV_COLORS[civId] ?? "#6b7280"
  const bg =
    score >= 60 ? "#22c55e" :
    score >= 20 ? "#84cc16" :
    score >= -20 ? "#6b7280" :
    score >= -60 ? "#f97316" :
    "#ef4444"

  return (
    <span
      className="relative inline-block"
      onMouseEnter={() => setHover(true)}
      onMouseLeave={() => setHover(false)}
    >
      <span
        className="block w-2 h-2 rounded-full border"
        style={{ background: bg, borderColor: `${color}66` }}
        aria-label={`${CIV_NAMES[civId] ?? civId}: ${score} (${moodLabel(score)})`}
      />
      {hover && (
        <span
          className="absolute bottom-4 left-1/2 -translate-x-1/2 z-20 whitespace-nowrap
                     bg-zinc-900 border border-zinc-700 rounded-md px-2 py-1 text-[10px] shadow-lg"
        >
          <span style={{ color }} className="font-semibold">
            {CIV_NAMES[civId] ?? civId}
          </span>
          <span className="text-zinc-400"> {score > 0 ? `+${score}` : score} · </span>
          <span style={{ color: bg }} className="font-medium">{moodLabel(score)}</span>
        </span>
      )}
    </span>
  )
}

"use client"

import { useEffect } from "react"
import { useFocusTrap } from "@/hooks/useFocusTrap"

interface ConfirmDialogProps {
  open: boolean
  title: string
  message: string
  confirmLabel?: string
  cancelLabel?: string
  isWorking?: boolean
  onConfirm: () => void
  onCancel: () => void
}

export default function ConfirmDialog({
  open, title, message,
  confirmLabel = "Confirm", cancelLabel = "Cancel",
  isWorking = false,
  onConfirm, onCancel,
}: ConfirmDialogProps) {
  const trapRef = useFocusTrap<HTMLDivElement>(open)

  useEffect(() => {
    if (!open) return
    const onKey = (e: KeyboardEvent) => {
      if (e.key === "Escape") onCancel()
    }
    window.addEventListener("keydown", onKey)
    return () => window.removeEventListener("keydown", onKey)
  }, [open, onCancel])

  if (!open) return null

  return (
    <div
      className="fixed inset-0 z-[90] flex items-center justify-center bg-zinc-950/80 backdrop-blur-sm"
      onClick={onCancel}
    >
      <div
        ref={trapRef}
        role="alertdialog"
        aria-modal="true"
        aria-label={title}
        onClick={(e) => e.stopPropagation()}
        className="max-w-sm w-full mx-4 rounded-2xl border border-zinc-800 bg-zinc-900 p-6 shadow-2xl"
      >
        <h2 className="text-base font-bold text-zinc-100 mb-2">{title}</h2>
        <p className="text-sm text-zinc-400 leading-relaxed mb-6">{message}</p>
        <div className="flex gap-3 justify-end">
          <button
            onClick={onCancel}
            disabled={isWorking}
            className="px-4 py-2 rounded-xl border border-zinc-700 text-zinc-400 text-sm
                       hover:text-zinc-200 hover:border-zinc-500 transition-colors
                       disabled:opacity-40"
          >
            {cancelLabel}
          </button>
          <button
            onClick={onConfirm}
            disabled={isWorking}
            className="px-4 py-2 rounded-xl bg-red-700 hover:bg-red-600 text-white text-sm
                       font-semibold transition-colors disabled:opacity-50"
          >
            {isWorking ? "Working…" : confirmLabel}
          </button>
        </div>
      </div>
    </div>
  )
}

"use client"

import { Component, type ReactNode } from "react"

interface Props {
  label: string
  children: ReactNode
}

interface State {
  hasError: boolean
}

export default class ErrorBoundary extends Component<Props, State> {
  state: State = { hasError: false }

  static getDerivedStateFromError(): State {
    return { hasError: true }
  }

  componentDidCatch(error: Error) {
    console.error(`[${this.props.label}] component failure:`, error)
  }

  render() {
    if (this.state.hasError) {
      return (
        <div className="flex items-center justify-center h-full p-4">
          <div className="text-center">
            <div className="text-xs font-mono text-red-400 mb-2">
              {"// "}{this.props.label.toUpperCase()} FAILURE — ATTEMPTING RECOVERY
            </div>
            <button
              onClick={() => this.setState({ hasError: false })}
              className="text-xs px-3 py-1.5 rounded-lg border border-zinc-700 text-zinc-400
                         hover:border-zinc-500 hover:text-zinc-200 transition-colors"
            >
              Retry
            </button>
          </div>
        </div>
      )
    }
    return this.props.children
  }
}

"use client"

import { useEffect, useMemo, useRef, useState } from "react"
import { useEventStore } from "@/store/eventStore"
import { CIV_COLORS, EVENT_META } from "@/lib/civColors"
import type { SimEvent } from "@/types"

const SKIP_TYPES = ["narrator", "civ_idle", "turn_start"]

type FeedFilter = "all" | "wars" | "diplomacy" | "world" | "narrator"

const FILTER_LABELS: Array<{ id: FeedFilter; label: string }> = [
  { id: "all", label: "ALL" },
  { id: "wars", label: "WARS" },
  { id: "diplomacy", label: "DIPLOMACY" },
  { id: "world", label: "WORLD" },
  { id: "narrator", label: "NARRATOR" },
]

const WAR_TYPES = new Set(["war_declaration", "territory_captured", "rebellion", "civ_eliminated"])
const DIPLOMACY_TYPES = new Set([
  "peace_treaty", "trade_offer", "trade_accepted", "trade_rejected",
  "alliance_formed", "alliance_broken", "relationship_shift",
])

function eventMatchesFilter(type: string, filter: FeedFilter): boolean {
  switch (filter) {
    case "all": return true
    case "narrator": return false
    case "wars": return WAR_TYPES.has(type)
    case "diplomacy": return DIPLOMACY_TYPES.has(type)
    case "world": return !WAR_TYPES.has(type) && !DIPLOMACY_TYPES.has(type)
  }
}

export default function EventFeed() {
  const events = useEventStore((s) => s.events)
  const narratorLog = useEventStore((s) => s.narratorLog)
  const bottomRef = useRef<HTMLDivElement>(null)
  const containerRef = useRef<HTMLDivElement>(null)
  const isAtBottom = useRef(true)

  const [filter, setFilter] = useState<FeedFilter>("all")
  const [collapsedTurns, setCollapsedTurns] = useState<Set<number>>(new Set())

  // Track scroll position
  const handleScroll = () => {
    const el = containerRef.current
    if (!el) return
    isAtBottom.current = el.scrollHeight - el.scrollTop - el.clientHeight < 60
  }

  // Auto-scroll when new content arrives
  useEffect(() => {
    if (isAtBottom.current) {
      bottomRef.current?.scrollIntoView({ behavior: "smooth" })
    }
  }, [events, narratorLog])

  const latestNarratorTurn = narratorLog.length
    ? narratorLog[narratorLog.length - 1].turn
    : -1

  // Group entries per turn
  const turns = useMemo(
    () => buildTurns(narratorLog, events),
    [narratorLog, events]
  )

  const toggleTurn = (turn: number) =>
    setCollapsedTurns((prev) => {
      const next = new Set(prev)
      if (next.has(turn)) next.delete(turn)
      else next.add(turn)
      return next
    })

  if (turns.length === 0) {
    return (
      <div className="flex items-center justify-center h-full">
        <div className="text-center px-4">
          <div className="text-2xl mb-2">📜</div>
          <p className="text-zinc-600 text-sm">History awaits...</p>
        </div>
      </div>
    )
  }

  return (
    <div className="h-full flex flex-col">
      {/* Filters */}
      <div className="flex gap-1 px-3 py-2 border-b border-zinc-800/70 flex-shrink-0 flex-wrap">
        {FILTER_LABELS.map(({ id, label }) => (
          <button
            key={id}
            onClick={() => setFilter(id)}
            aria-pressed={filter === id}
            className={`text-[9px] font-semibold tracking-wider px-2 py-1 rounded-md border transition-colors ${
              filter === id
                ? "border-zinc-500 bg-zinc-800 text-zinc-100"
                : "border-zinc-800 text-zinc-600 hover:text-zinc-400 hover:border-zinc-700"
            }`}
          >
            {label}
          </button>
        ))}
      </div>

      <div
        ref={containerRef}
        onScroll={handleScroll}
        role="status"
        aria-live="polite"
        aria-label="Event chronicle"
        className="flex-1 overflow-y-auto px-4 py-3 space-y-2"
      >
        {turns.map(({ turn, turnEvents, narration }) => {
          const visibleEvents = turnEvents.filter((e) => eventMatchesFilter(e.type, filter))
          const showNarration =
            narration !== null && (filter === "all" || filter === "narrator")
          if (visibleEvents.length === 0 && !showNarration) return null
          const collapsed = collapsedTurns.has(turn)

          return (
            <div key={turn}>
              {/* Collapsible turn header */}
              <button
                onClick={() => toggleTurn(turn)}
                aria-expanded={!collapsed}
                className="w-full flex items-center gap-2 py-1.5 text-left group"
              >
                <span className="text-[10px] font-semibold text-zinc-600 group-hover:text-zinc-400
                                 tracking-widest font-mono transition-colors">
                  {collapsed ? "▸" : "▾"} TURN {String(turn).padStart(2, "0")}
                </span>
                <span className="flex-1 h-px bg-zinc-800/80" />
                {collapsed && (
                  <span className="text-[9px] text-zinc-700">
                    {visibleEvents.length + (showNarration ? 1 : 0)} entries
                  </span>
                )}
              </button>

              {!collapsed && (
                <div className="space-y-2">
                  {visibleEvents.map((ev, i) => (
                    <EventCard key={`${ev.id ?? ev.type}-${i}`} event={ev} />
                  ))}
                  {showNarration && (
                    <NarratorBlock
                      turn={turn}
                      text={narration!}
                      isLatest={turn === latestNarratorTurn}
                    />
                  )}
                </div>
              )}
            </div>
          )
        })}
        <div ref={bottomRef} />
      </div>
    </div>
  )
}

function NarratorBlock({ turn, text, isLatest }: { turn: number; text: string; isLatest: boolean }) {
  return (
    <div
      data-event-type="narrator"
      className={`feed-enter border-l-2 pl-3 py-1 rounded-r ${
        isLatest
          ? "border-amber-400 narrator-latest"
          : "border-amber-500/60"
      }`}
    >
      <div className={`text-[10px] font-medium uppercase tracking-widest mb-1 ${
        isLatest ? "text-amber-400" : "text-amber-500/60"
      }`}>
        Turn {turn}
      </div>
      <p className="text-sm text-zinc-300 italic leading-relaxed">
        &ldquo;{text}&rdquo;
      </p>
    </div>
  )
}

function EventCard({ event }: { event: SimEvent }) {
  const meta = EVENT_META[event.type] ?? { icon: "📌", color: "#6b7280", label: event.type }

  if (SKIP_TYPES.includes(event.type)) return null
  if (event.type === "relationship_shift") return <RelationshipShiftCard event={event} />

  return (
    <div
      data-event-type={event.type}
      className="feed-enter flex items-start gap-2.5 rounded-lg bg-zinc-900/60 px-3 py-2 border border-zinc-800/50"
    >
      <span className="text-sm flex-shrink-0 mt-0.5">{meta.icon}</span>
      <div className="min-w-0">
        <div className="flex items-center gap-2 flex-wrap">
          <span
            className="text-[10px] font-semibold uppercase tracking-wider"
            style={{ color: meta.color }}
          >
            {meta.label}
          </span>

          {event.actor && (
            <span
              className="text-[10px] font-medium"
              style={{ color: CIV_COLORS[event.actor] ?? "#9ca3af" }}
            >
              {event.actor}
            </span>
          )}

          {event.target && event.target !== event.actor && (
            <>
              <span className="text-zinc-600 text-[10px]">→</span>
              <span
                className="text-[10px] font-medium"
                style={{ color: CIV_COLORS[event.target] ?? "#9ca3af" }}
              >
                {event.target}
              </span>
            </>
          )}
        </div>

        {event.narrative && (
          <p className="text-xs text-zinc-500 mt-0.5 leading-relaxed">
            {event.narrative}
          </p>
        )}
      </div>
    </div>
  )
}

function RelationshipShiftCard({ event }: { event: SimEvent }) {
  const data = event.data as { before?: number; after?: number }
  const before = data.before ?? 0
  const after = data.after ?? 0
  const delta = after - before
  const moodAfter =
    after >= 60 ? "allied" : after >= 20 ? "friendly" :
    after >= -20 ? "neutral" : after >= -60 ? "hostile" : "at war"
  const deltaColor = delta > 0 ? "#22c55e" : "#ef4444"

  const toPct = (v: number) => ((v + 100) / 200) * 100

  return (
    <div
      data-event-type="relationship_shift"
      className="feed-enter rounded-lg bg-zinc-900/60 px-3 py-2 border border-zinc-800/50"
    >
      <div className="flex items-center gap-2 flex-wrap text-[10px]">
        <span style={{ color: deltaColor }} className="font-semibold">
          {delta > 0 ? "↑" : "↓"}
        </span>
        <span className="font-medium uppercase" style={{ color: CIV_COLORS[event.actor ?? ""] ?? "#9ca3af" }}>
          {event.actor}
        </span>
        <span className="text-zinc-600">↔</span>
        <span className="font-medium uppercase" style={{ color: CIV_COLORS[event.target ?? ""] ?? "#9ca3af" }}>
          {event.target}
        </span>
        <span className="font-semibold tabular-nums" style={{ color: deltaColor }}>
          {delta > 0 ? `+${delta}` : delta}
        </span>
        <span className="text-zinc-500">(now {moodAfter})</span>
      </div>
      {/* Before/after relationship meter */}
      <div className="relative mt-1.5 h-1.5 bg-zinc-800 rounded-full overflow-hidden">
        <div className="absolute inset-y-0 left-1/2 w-px bg-zinc-600" />
        <div
          className="absolute inset-y-0 w-1 rounded-full bg-zinc-500"
          style={{ left: `calc(${toPct(before)}% - 2px)` }}
          title={`before: ${before}`}
        />
        <div
          className="absolute inset-y-0 w-1 rounded-full"
          style={{ left: `calc(${toPct(after)}% - 2px)`, background: deltaColor }}
          title={`after: ${after}`}
        />
      </div>
    </div>
  )
}

// ── Turn grouping ─────────────────────────────────────────────────────────────

interface TurnGroup {
  turn: number
  turnEvents: SimEvent[]
  narration: string | null
}

function buildTurns(
  narratorLog: Array<{ turn: number; text: string }>,
  events: SimEvent[],
): TurnGroup[] {
  const maxTurn = Math.max(
    ...narratorLog.map((n) => n.turn),
    ...events.map((e) => e.turn),
    0,
  )

  const groups: TurnGroup[] = []
  for (let t = 1; t <= maxTurn; t++) {
    const turnEvents = events.filter(
      (e) => e.turn === t && !SKIP_TYPES.includes(e.type)
    )
    const narration = narratorLog.find((n) => n.turn === t)?.text ?? null
    if (turnEvents.length === 0 && narration === null) continue
    groups.push({ turn: t, turnEvents, narration })
  }
  return groups
}

"use client"

import { useEffect, useRef } from "react"
import * as THREE from "three"

/**
 * WebGL hex-terrain backdrop for the landing page.
 * An instanced field of hexagonal columns ripples slowly outward from the
 * center; a handful of tiles glow in the four civ colors. The camera drifts
 * and follows the pointer with a soft parallax.
 *
 * Honors prefers-reduced-motion (renders one static frame) and pauses the
 * render loop while the tab is hidden.
 */

const BG = 0x09090b // zinc-950
const BASE_TILE = 0x18181b // zinc-900
const CIV_ACCENTS = [0xc0392b, 0x27ae60, 0xf39c12, 0x8e44ad, 0x6366f1]

const HEX = 1.0 // hex radius in world units
const RADIUS = 16 // grid radius in hexes
const GAP = 0.94 // shrink factor so seams show between tiles

export default function HexFieldCanvas() {
  const containerRef = useRef<HTMLDivElement>(null)

  useEffect(() => {
    const container = containerRef.current
    if (!container) return

    let renderer: THREE.WebGLRenderer
    try {
      renderer = new THREE.WebGLRenderer({
        antialias: true,
        alpha: true,
        powerPreference: "high-performance",
      })
    } catch {
      return // WebGL unavailable — the CSS gradient behind us still shows
    }

    const reducedMotion = window.matchMedia("(prefers-reduced-motion: reduce)").matches

    renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2))
    renderer.setClearColor(BG, 0)
    container.appendChild(renderer.domElement)

    const scene = new THREE.Scene()
    scene.fog = new THREE.Fog(BG, 26, 64)

    const camera = new THREE.PerspectiveCamera(42, 1, 0.1, 200)
    camera.position.set(0, 20, 30)
    camera.lookAt(0, 0, 4)

    // ── Lights ──────────────────────────────────────────────────────────────
    scene.add(new THREE.AmbientLight(0x6366f1, 0.35))
    const key = new THREE.DirectionalLight(0xa5b4fc, 1.1)
    key.position.set(-12, 22, 10)
    scene.add(key)
    const warm = new THREE.PointLight(0xf39c12, 60, 45, 2)
    warm.position.set(14, 7, -8)
    scene.add(warm)
    const cool = new THREE.PointLight(0x6366f1, 90, 50, 2)
    cool.position.set(-12, 8, 6)
    scene.add(cool)

    // ── Instanced hex columns ────────────────────────────────────────────────
    const cells: Array<{ x: number; z: number; phase: number; base: number }> = []
    for (let q = -RADIUS; q <= RADIUS; q++) {
      for (let r = Math.max(-RADIUS, -q - RADIUS); r <= Math.min(RADIUS, -q + RADIUS); r++) {
        const x = HEX * Math.sqrt(3) * (q + r / 2)
        const z = HEX * 1.5 * r
        const dist = Math.sqrt(x * x + z * z)
        cells.push({
          x,
          z,
          phase: dist * 0.55 + Math.random() * 0.6,
          base: 0.4 + Math.random() * 0.5,
        })
      }
    }

    const geometry = new THREE.CylinderGeometry(HEX * GAP, HEX * GAP, 1, 6)
    const material = new THREE.MeshStandardMaterial({
      roughness: 0.35,
      metalness: 0.55,
      flatShading: true,
    })
    const mesh = new THREE.InstancedMesh(geometry, material, cells.length)
    mesh.instanceMatrix.setUsage(THREE.DynamicDrawUsage)

    const baseColor = new THREE.Color(BASE_TILE)
    const tmpColor = new THREE.Color()
    cells.forEach((cell, i) => {
      if (Math.random() < 0.035) {
        // Civ-colored accent tile
        tmpColor.setHex(CIV_ACCENTS[Math.floor(Math.random() * CIV_ACCENTS.length)])
        cell.base += 0.8
      } else {
        // Slight per-tile brightness variation on the zinc base
        tmpColor.copy(baseColor).offsetHSL(0, 0, (Math.random() - 0.5) * 0.035)
      }
      mesh.setColorAt(i, tmpColor)
    })
    scene.add(mesh)

    const dummy = new THREE.Object3D()
    const layout = (t: number) => {
      for (let i = 0; i < cells.length; i++) {
        const c = cells[i]
        const h = c.base + 0.55 * (1 + Math.sin(t * 0.9 - c.phase))
        dummy.position.set(c.x, h / 2 - 1.2, c.z)
        dummy.scale.set(1, h, 1)
        dummy.updateMatrix()
        mesh.setMatrixAt(i, dummy.matrix)
      }
      mesh.instanceMatrix.needsUpdate = true
    }

    // ── Resize ──────────────────────────────────────────────────────────────
    const resize = () => {
      const { clientWidth: w, clientHeight: h } = container
      if (!w || !h) return
      renderer.setSize(w, h)
      camera.aspect = w / h
      camera.updateProjectionMatrix()
      if (reducedMotion) {
        layout(0)
        renderer.render(scene, camera)
      }
    }
    const ro = new ResizeObserver(resize)
    ro.observe(container)
    resize()

    if (reducedMotion) {
      layout(0)
      renderer.render(scene, camera)
      return () => {
        ro.disconnect()
        geometry.dispose()
        material.dispose()
        renderer.dispose()
        renderer.domElement.remove()
      }
    }

    // ── Pointer parallax ─────────────────────────────────────────────────────
    const mouse = { x: 0, y: 0 }
    const onPointer = (e: PointerEvent) => {
      mouse.x = (e.clientX / window.innerWidth) * 2 - 1
      mouse.y = (e.clientY / window.innerHeight) * 2 - 1
    }
    window.addEventListener("pointermove", onPointer)

    // ── Render loop ──────────────────────────────────────────────────────────
    let raf = 0
    const clock = new THREE.Clock()
    let elapsed = 0
    const animate = () => {
      raf = requestAnimationFrame(animate)
      elapsed += clock.getDelta()
      layout(elapsed)

      // Slow drift + pointer parallax (eased)
      const targetX = Math.sin(elapsed * 0.06) * 3 + mouse.x * 2.2
      const targetY = 20 - mouse.y * 1.4
      camera.position.x += (targetX - camera.position.x) * 0.03
      camera.position.y += (targetY - camera.position.y) * 0.03
      camera.lookAt(0, 0, 4)

      renderer.render(scene, camera)
    }
    animate()

    const onVisibility = () => {
      if (document.hidden) {
        cancelAnimationFrame(raf)
        clock.stop()
      } else {
        clock.start()
        animate()
      }
    }
    document.addEventListener("visibilitychange", onVisibility)

    return () => {
      cancelAnimationFrame(raf)
      document.removeEventListener("visibilitychange", onVisibility)
      window.removeEventListener("pointermove", onPointer)
      ro.disconnect()
      geometry.dispose()
      material.dispose()
      renderer.dispose()
      renderer.domElement.remove()
    }
  }, [])

  return (
    <div
      ref={containerRef}
      aria-hidden="true"
      className="absolute inset-0 [&>canvas]:block [&>canvas]:h-full [&>canvas]:w-full"
    />
  )
}

"use client"

import { useEffect, useRef, useMemo, useState } from "react"
import * as d3 from "d3"
import { useWorldStore } from "@/store/worldStore"
import { useUiStore } from "@/store/uiStore"
import { hexToPixel, gridBounds, tilesBounds, HEX_SIZE } from "@/lib/hexUtils"
import { CIV_COLORS, CIV_NAMES, TILE_COLORS } from "@/lib/civColors"
import type { HexTile } from "@/types"

const PAD = 20

// Axial neighbor directions, ordered so edge i sits between corner i and corner i+1
// (pointy-top, corners at 60·i − 30 degrees)
const AXIAL_DIRS: Array<[number, number]> = [
  [1, 0], [0, 1], [-1, 1], [-1, 0], [0, -1], [1, -1],
]

interface TooltipState {
  x: number
  y: number
  tile: HexTile
}

const tileKey = (t: { q: number; r: number }) => `${t.q},${t.r}`

export default function HexGrid() {
  const svgRef = useRef<SVGSVGElement>(null)
  const containerRef = useRef<HTMLDivElement>(null)
  const zoomRef = useRef<d3.ZoomBehavior<SVGSVGElement, unknown> | null>(null)
  const prevTilesRef = useRef<Map<string, string | null> | null>(null)

  const worldState = useWorldStore((s) => s.worldState)
  const focusedCiv = useUiStore((s) => s.focusedCiv)
  const clearFocusedCiv = useUiStore((s) => s.clearFocusedCiv)

  const [tooltip, setTooltip] = useState<TooltipState | null>(null)

  // Derive bounds from the actual tiles so any grid size renders correctly
  const tiles = worldState?.tiles
  const bounds = useMemo(
    () => (tiles?.length ? tilesBounds(tiles, HEX_SIZE) : gridBounds(15, HEX_SIZE)),
    [tiles]
  )

  const center = (t: { q: number; r: number }) => {
    const { x, y } = hexToPixel(t.q, t.r, HEX_SIZE)
    return { x: x - bounds.minX + PAD, y: y - bounds.minY + PAD }
  }

  const cornerPoints = (t: { q: number; r: number }, size = HEX_SIZE - 1) => {
    const { x, y } = center(t)
    return Array.from({ length: 6 }, (_, i) => {
      const angle = (Math.PI / 180) * (60 * i - 30)
      return [x + size * Math.cos(angle), y + size * Math.sin(angle)] as [number, number]
    })
  }

  // ── Zoom / pan (once) ─────────────────────────────────────────────────────
  useEffect(() => {
    if (!svgRef.current) return
    const svg = d3.select(svgRef.current)
    const zoom = d3
      .zoom<SVGSVGElement, unknown>()
      .scaleExtent([0.5, 6])
      .on("zoom", (event) => {
        svg.select<SVGGElement>(".viewport").attr("transform", event.transform.toString())
        setTooltip(null)
      })
    svg.call(zoom)
    zoomRef.current = zoom
    return () => {
      svg.on(".zoom", null)
    }
  }, [])

  // ── Tile rendering with diff updates ──────────────────────────────────────
  useEffect(() => {
    if (!svgRef.current || !worldState?.tiles) return

    const svg = d3.select(svgRef.current)
    const tiles = worldState.tiles
    const hexGroup = svg.select<SVGGElement>(".hex-group")
    const unitGroup = svg.select<SVGGElement>(".unit-group")
    const borderGroup = svg.select<SVGGElement>(".border-group")

    const prevOwners = prevTilesRef.current
    const changed: HexTile[] = []
    if (prevOwners) {
      for (const t of tiles) {
        if (prevOwners.get(tileKey(t)) !== (t.owner ?? null)) changed.push(t)
      }
    }
    prevTilesRef.current = new Map(tiles.map((t) => [tileKey(t), t.owner ?? null]))

    // Enter (first paint or grid change)
    const hexes = hexGroup
      .selectAll<SVGPolygonElement, HexTile>("polygon.hex")
      .data(tiles, (d) => tileKey(d))

    hexes
      .enter()
      .append("polygon")
      .attr("class", "hex")
      .attr("points", (d) => cornerPoints(d).map((p) => p.join(",")).join(" "))
      .attr("fill", (d) => getTileFill(d))
      .attr("stroke", (d) => getTileStroke(d))
      .attr("stroke-width", (d) => (d.owner ? 1.5 : 0.5))
      .style("cursor", "pointer")
      .on("mouseenter", function (event: MouseEvent, d) {
        d3.select(this)
          .raise()
          .attr("fill-opacity", 0.8)
          .attr("stroke", "#fafafa")
          .attr("stroke-width", 2)
        const rect = containerRef.current!.getBoundingClientRect()
        setTooltip({ x: event.clientX - rect.left, y: event.clientY - rect.top, tile: d })
      })
      .on("mouseleave", function (_event, d) {
        d3.select(this)
          .attr("fill-opacity", 1)
          .attr("stroke", getTileStroke(d))
          .attr("stroke-width", d.owner ? 1.5 : 0.5)
        setTooltip(null)
      })

    hexes.exit().remove()

    // Re-bind data so tooltips show fresh tile values, but only animate changed tiles
    const all = hexGroup
      .selectAll<SVGPolygonElement, HexTile>("polygon.hex")
      .data(tiles, (d) => tileKey(d))

    if (!prevOwners) {
      all
        .attr("fill", (d) => getTileFill(d))
        .attr("stroke", (d) => getTileStroke(d))
        .attr("stroke-width", (d) => (d.owner ? 1.5 : 0.5))
    } else if (changed.length > 0) {
      const changedKeys = new Set(changed.map(tileKey))
      const changedSel = all.filter((d) => changedKeys.has(tileKey(d)))

      // Battle flash: white pulse, then settle into the new owner's blend
      changedSel
        .attr("fill", "#ffffff")
        .transition("flash")
        .duration(600)
        .attr("fill", (d) => getTileFill(d))

      // Turn-diff glow: thick outline in the new owner's color, fading over 2s
      changedSel
        .attr("stroke", (d) => (d.owner ? CIV_COLORS[d.owner] ?? "#fff" : "#ffffff66"))
        .attr("stroke-width", 4)
        .transition("glow")
        .duration(2000)
        .attr("stroke", (d) => getTileStroke(d))
        .attr("stroke-width", (d) => (d.owner ? 1.5 : 0.5))
    }

    // ── Unit markers ─────────────────────────────────────────────────────────
    const unitTiles = tiles.filter((t) => t.has_unit)
    const units = unitGroup
      .selectAll<SVGRectElement, HexTile>("rect.unit")
      .data(unitTiles, (d) => tileKey(d))

    units
      .enter()
      .append("rect")
      .attr("class", "unit")
      .attr("width", 7)
      .attr("height", 7)
      .attr("pointer-events", "none")
      .merge(units)
      .attr("transform", (d) => {
        const { x, y } = center(d)
        return `translate(${x},${y}) rotate(45) translate(-3.5,-3.5)`
      })
      .attr("fill", (d) => (d.owner ? CIV_COLORS[d.owner] ?? "#fff" : "#ffffffaa"))
      .attr("stroke", "#000")
      .attr("stroke-width", 0.75)

    units.exit().remove()

    // ── Territory borders ────────────────────────────────────────────────────
    const tileMap = new Map(tiles.map((t) => [tileKey(t), t]))
    const segmentsByCiv = new Map<string, string[]>()

    for (const t of tiles) {
      if (!t.owner) continue
      const corners = cornerPoints(t)
      AXIAL_DIRS.forEach(([dq, dr], i) => {
        const neighbor = tileMap.get(`${t.q + dq},${t.r + dr}`)
        if (neighbor && neighbor.owner === t.owner) return
        const [x1, y1] = corners[i]
        const [x2, y2] = corners[(i + 1) % 6]
        const segs = segmentsByCiv.get(t.owner!) ?? []
        segs.push(`M${x1.toFixed(1)},${y1.toFixed(1)}L${x2.toFixed(1)},${y2.toFixed(1)}`)
        segmentsByCiv.set(t.owner!, segs)
      })
    }

    const borders = borderGroup
      .selectAll<SVGPathElement, [string, string[]]>("path.border")
      .data(Array.from(segmentsByCiv.entries()), (d) => d[0])

    borders
      .enter()
      .append("path")
      .attr("class", "border")
      .attr("fill", "none")
      .attr("stroke-width", 2.5)
      .attr("stroke-linecap", "round")
      .attr("pointer-events", "none")
      .merge(borders)
      .attr("stroke", (d) => CIV_COLORS[d[0]] ?? "#fff")
      .attr("d", (d) => d[1].join(""))

    borders.exit().remove()
    // center/cornerPoints derive only from bounds, which is already a dependency
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [worldState, bounds])

  // ── Focused-civ dimming ────────────────────────────────────────────────────
  useEffect(() => {
    if (!svgRef.current) return
    const svg = d3.select(svgRef.current)
    svg
      .selectAll<SVGPolygonElement, HexTile>("polygon.hex")
      .transition("focus")
      .duration(250)
      .attr("opacity", (d) => (!focusedCiv || d.owner === focusedCiv ? 1 : 0.2))
    svg
      .selectAll<SVGPathElement, [string, string[]]>("path.border")
      .transition("focus")
      .duration(250)
      .attr("opacity", (d) => (!focusedCiv || d[0] === focusedCiv ? 1 : 0.15))
  }, [focusedCiv, worldState])

  const resetView = () => {
    if (!svgRef.current || !zoomRef.current) return
    d3.select(svgRef.current)
      .transition()
      .duration(400)
      .call(zoomRef.current.transform, d3.zoomIdentity)
  }

  const zoomBy = (factor: number) => {
    if (!svgRef.current || !zoomRef.current) return
    d3.select(svgRef.current)
      .transition()
      .duration(250)
      .call(zoomRef.current.scaleBy, factor)
  }

  if (!worldState) {
    return (
      <div className="flex items-center justify-center h-full">
        <div className="text-center">
          <div className="text-3xl mb-3 animate-pulse">🌍</div>
          <p className="text-zinc-500 text-sm">Waiting for world generation...</p>
        </div>
      </div>
    )
  }

  const svgW = bounds.width + PAD * 2
  const svgH = bounds.height + PAD * 2

  const presentCivs = Array.from(
    new Set(worldState.tiles.map((t) => t.owner).filter((o): o is string => !!o))
  )

  return (
    <div
      ref={containerRef}
      className="relative w-full h-full overflow-hidden rounded-xl
                 bg-[radial-gradient(ellipse_at_center,#121217_0%,#09090b_75%)]"
    >
      {/* Vignette */}
      <div
        aria-hidden="true"
        className="absolute inset-0 pointer-events-none
                   bg-[radial-gradient(ellipse_at_center,transparent_55%,rgba(0,0,0,0.45)_100%)]"
      />
      <svg
        ref={svgRef}
        width="100%"
        height="100%"
        viewBox={`0 0 ${svgW} ${svgH}`}
        preserveAspectRatio="xMidYMid meet"
        className="block"
        role="img"
        aria-label="Hex world map"
        onClick={(e) => {
          if (e.target === e.currentTarget) clearFocusedCiv()
        }}
      >
        <g className="viewport">
          <g className="hex-group" />
          <g className="border-group" />
          <g className="unit-group" />
        </g>
      </svg>

      {/* Map controls */}
      <div className="absolute top-3 right-3 flex flex-col items-end gap-1.5">
        <div className="flex rounded-lg border border-zinc-700 bg-zinc-900/80 overflow-hidden">
          <button
            onClick={() => zoomBy(1.4)}
            aria-label="Zoom in"
            className="w-7 h-7 flex items-center justify-center text-zinc-400
                       hover:text-zinc-100 hover:bg-zinc-800 transition-colors text-sm font-bold"
          >
            +
          </button>
          <span className="w-px bg-zinc-700" aria-hidden="true" />
          <button
            onClick={() => zoomBy(1 / 1.4)}
            aria-label="Zoom out"
            className="w-7 h-7 flex items-center justify-center text-zinc-400
                       hover:text-zinc-100 hover:bg-zinc-800 transition-colors text-sm font-bold"
          >
            −
          </button>
        </div>
        <button
          onClick={resetView}
          aria-label="Reset map view"
          className="text-[10px] px-2.5 py-1.5 rounded-lg border border-zinc-700
                     bg-zinc-900/80 text-zinc-400 hover:border-zinc-500 hover:text-zinc-200
                     font-medium uppercase tracking-wider transition-colors"
        >
          Reset View
        </button>
      </div>

      {/* Legend — pinned bottom-left, unaffected by zoom */}
      <div className="absolute bottom-3 left-3 bg-zinc-900/85 border border-zinc-800 rounded-lg
                      px-3 py-2 space-y-1 pointer-events-none">
        {presentCivs.map((civId) => (
          <div key={civId} className="flex items-center gap-2">
            <span
              className="w-2.5 h-2.5 rounded-sm border border-black/40"
              style={{ background: CIV_COLORS[civId] ?? "#6b7280" }}
            />
            <span className="text-[10px] text-zinc-400 font-medium">
              {CIV_NAMES[civId] ?? civId}
            </span>
          </div>
        ))}
        {presentCivs.length === 0 && (
          <span className="text-[10px] text-zinc-600">Unclaimed world</span>
        )}
      </div>

      {/* Tooltip */}
      {tooltip && (
        <div
          className="absolute pointer-events-none z-10 bg-zinc-900 border border-zinc-700
                     rounded-lg px-3 py-2 text-xs shadow-xl"
          style={{ left: tooltip.x + 14, top: tooltip.y - 10, transform: "translateY(-50%)" }}
        >
          <div className="font-semibold text-zinc-100 capitalize mb-1">
            {tooltip.tile.tile_type}
          </div>
          {tooltip.tile.owner && (
            <div
              className="text-xs font-medium mb-1"
              style={{ color: CIV_COLORS[tooltip.tile.owner] ?? "#fff" }}
            >
              {CIV_NAMES[tooltip.tile.owner] ?? tooltip.tile.owner}
            </div>
          )}
          <div className="text-zinc-400 space-y-0.5">
            <div>🌾 {tooltip.tile.food.toFixed(1)}</div>
            <div>💰 {tooltip.tile.gold.toFixed(1)}</div>
            <div>🪨 {tooltip.tile.stone.toFixed(1)}</div>
          </div>
          {tooltip.tile.has_unit && (
            <div className="text-zinc-300 mt-1">⬥ Unit garrisoned</div>
          )}
          <div className="text-zinc-600 mt-1">q={tooltip.tile.q} r={tooltip.tile.r}</div>
        </div>
      )}
    </div>
  )
}

function getTileFill(d: HexTile): string {
  const base = TILE_COLORS[d.tile_type] ?? "#4a4a4a"
  if (!d.owner) return base

  const civColor = CIV_COLORS[d.owner]
  if (!civColor) return base

  // Blend civ color over tile base
  return blendColors(base, civColor, 0.55)
}

function getTileStroke(d: HexTile): string {
  if (d.owner) return CIV_COLORS[d.owner] ?? "#ffffff33"
  return "#ffffff18"
}

function blendColors(base: string, overlay: string, alpha: number): string {
  const b = hexToRgb(base)
  const o = hexToRgb(overlay)
  if (!b || !o) return base
  const r = Math.round(b.r * (1 - alpha) + o.r * alpha)
  const g = Math.round(b.g * (1 - alpha) + o.g * alpha)
  const bl = Math.round(b.b * (1 - alpha) + o.b * alpha)
  return `rgb(${r},${g},${bl})`
}

function hexToRgb(hex: string) {
  const result = /^#?([a-f\d]{2})([a-f\d]{2})([a-f\d]{2})$/i.exec(hex)
  return result
    ? { r: parseInt(result[1], 16), g: parseInt(result[2], 16), b: parseInt(result[3], 16) }
    : null
}

/** Centralised SVG icon set — replace emoji chrome with crisp vector icons */

import { JSX } from "react"

interface IconProps {
  size?: number
  className?: string
}

const icon = (path: JSX.Element, vb = "0 0 24 24") =>
  function Icon({ size = 16, className = "" }: IconProps): JSX.Element {
    return (
      <svg
        width={size}
        height={size}
        viewBox={vb}
        fill="none"
        stroke="currentColor"
        strokeWidth={1.75}
        strokeLinecap="round"
        strokeLinejoin="round"
        className={className}
        aria-hidden="true"
      >
        {path}
      </svg>
    )
  }

