"use client"

import { useState } from "react"
import { useWorldStore } from "@/store/worldStore"
import { CIV_COLORS, CIV_ICONS, CIV_NAMES } from "@/lib/civColors"

const CIV_ORDER = ["ironhold", "verdant", "merchants", "conclave"]

/** Map −100…100 to a deep-red → grey → deep-green background */
function scoreColor(score: number): string {
  const t = Math.max(-100, Math.min(100, score)) / 100
  if (t >= 0) {
    const k = Math.round(t * 110)
    return `rgb(${40 - Math.round(t * 20)}, ${60 + k}, ${50})`
  }
  const k = Math.round(-t * 130)
  return `rgb(${60 + k}, ${40 - Math.round(-t * 15)}, ${45})`
}

export default function RelationshipMatrix() {
  const civStates = useWorldStore((s) => s.civStates)
  const [open, setOpen] = useState(false)

  const civs = CIV_ORDER.filter((id) => civStates[id])
  if (civs.length === 0) return null

  return (
    <div className="border-t border-zinc-800/70">
      <button
        onClick={() => setOpen((o) => !o)}
        aria-expanded={open}
        className="w-full flex items-center gap-2 px-4 py-1.5 text-left group"
      >
        <span className="text-[10px] font-semibold uppercase tracking-widest text-zinc-600
                         group-hover:text-zinc-400 transition-colors">
          {open ? "▾" : "▸"} Relationship Matrix
        </span>
        <span className="flex-1 h-px bg-zinc-800/60" />
      </button>

      {open && (
        <div className="px-4 pb-3">
          <table className="border-separate border-spacing-0.5">
            <thead>
              <tr>
                <th className="w-8" aria-hidden="true" />
                {civs.map((id) => (
                  <th key={id} className="w-12 text-center" title={CIV_NAMES[id] ?? id}>
                    <span className="text-xs">{CIV_ICONS[id]}</span>
                  </th>
                ))}
              </tr>
            </thead>
            <tbody>
              {civs.map((rowId) => (
                <tr key={rowId}>
                  <td className="text-center pr-1" title={CIV_NAMES[rowId] ?? rowId}>
                    <span className="text-xs">{CIV_ICONS[rowId]}</span>
                  </td>
                  {civs.map((colId) => {
                    if (rowId === colId) {
                      return (
                        <td key={colId}
                            className="w-12 h-7 rounded text-center bg-zinc-900 border border-zinc-800">
                          <span className="text-[10px]" style={{ color: CIV_COLORS[rowId] }}>—</span>
                        </td>
                      )
                    }
                    const score = civStates[rowId]?.relationships?.[colId]
                    return (
                      <td
                        key={colId}
                        className="w-12 h-7 rounded text-center"
                        style={{ background: score === undefined ? "#18181b" : scoreColor(score) }}
                        title={`${CIV_NAMES[rowId]} → ${CIV_NAMES[colId]}: ${score ?? "?"}`}
                      >
                        <span className="text-[10px] font-semibold text-white/90 tabular-nums">
                          {score === undefined ? "?" : score > 0 ? `+${score}` : score}
                        </span>
                      </td>
                    )
                  })}
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}
    </div>
  )
}

"use client"

import TurnTimeline from "@/components/TurnTimeline"
import { ChevronLeft, ChevronRight, ArrowRight } from "@/components/Icons"

interface ReplayControlsProps {
  totalTurns: number
  replayTurn: number
  isLoading: boolean
  isReplayMode: boolean
  goToTurn: (turn: number) => void
  exitReplay: () => void
}

export default function ReplayControls({
  totalTurns, replayTurn, isLoading, isReplayMode, goToTurn, exitReplay,
}: ReplayControlsProps) {
  return (
    <div className="flex items-center gap-4 px-4 py-2 bg-zinc-950 border-t border-zinc-800">

      {/* Replay label */}
      <div className="flex items-center gap-2 flex-shrink-0">
        <span className="text-[10px] font-semibold uppercase tracking-widest text-amber-500">
          Replay
        </span>
        {isLoading && (
          <div className="w-3 h-3 border border-zinc-600 border-t-amber-500 rounded-full animate-spin" />
        )}
      </div>

      {/* Turn counter */}
      <div className="flex items-center gap-2 flex-shrink-0">
        <span className="text-xs text-zinc-500">Turn</span>
        <span className="text-sm font-bold text-zinc-100 tabular-nums w-6 text-center">
          {replayTurn}
        </span>
        <span className="text-xs text-zinc-600">/ {totalTurns}</span>
      </div>

      {/* Turn timeline scrubber */}
      <TurnTimeline
        totalTurns={totalTurns}
        currentTurn={replayTurn}
        onSelect={goToTurn}
        disabled={isLoading}
      />

      {/* Step buttons */}
      <div className="flex gap-1 flex-shrink-0">
        <button
          onClick={() => goToTurn(Math.max(0, replayTurn - 1))}
          disabled={replayTurn <= 0 || isLoading}
          aria-label="Previous turn"
          className="w-7 h-7 rounded-lg border border-zinc-700 text-zinc-400
                     hover:border-zinc-500 hover:text-zinc-200 disabled:opacity-30
                     transition-colors flex items-center justify-center"
        >
          <ChevronLeft size={13} />
        </button>
        <button
          onClick={() => goToTurn(Math.min(totalTurns, replayTurn + 1))}
          disabled={replayTurn >= totalTurns || isLoading}
          aria-label="Next turn"
          className="w-7 h-7 rounded-lg border border-zinc-700 text-zinc-400
                     hover:border-zinc-500 hover:text-zinc-200 disabled:opacity-30
                     transition-colors flex items-center justify-center"
        >
          <ChevronRight size={13} />
        </button>
      </div>

      {/* Jump to latest */}
      {isReplayMode && (
        <button
          onClick={exitReplay}
          className="flex items-center gap-1.5 text-[10px] px-2.5 py-1 rounded-lg border border-amber-800
                     text-amber-500 hover:border-amber-600 transition-colors flex-shrink-0"
        >
          Latest <ArrowRight size={10} />
        </button>
      )}

    </div>
  )
}

